<?php
namespace WPMailDesk\Admin;
final class AdminApp{private string$hook='';public function register():void{add_action('admin_menu',array($this,'menu'));add_action('admin_enqueue_scripts',array($this,'assets'));}public function menu():void{$this->hook=add_menu_page(__('MailDesk','wp-maildesk'),__('MailDesk','wp-maildesk'),'wpmd_access_mail','wp-maildesk',array($this,'render'),'dashicons-email-alt2',25);}public function assets(string$hook):void{if($hook!==$this->hook)return;wp_enqueue_style('wpmd-admin',WPMD_URL.'assets/css/admin.css',array(),WPMD_VERSION);wp_enqueue_script('wpmd-admin',WPMD_URL.'assets/js/admin.js',array('wp-api-fetch','wp-i18n'),WPMD_VERSION,true);wp_localize_script('wpmd-admin','WPMD',array('root'=>esc_url_raw(rest_url('wpmd/v1/')),'nonce'=>wp_create_nonce('wp_rest'),'user'=>get_current_user_id()));}public function render():void{if(!current_user_can('wpmd_access_mail'))wp_die(esc_html__('You do not have permission to access MailDesk.','wp-maildesk'));echo '<div class="wrap wpmd-wrap"><div id="wpmd-app"><div class="wpmd-loading">'.esc_html__('Loading MailDesk…','wp-maildesk').'</div></div></div>';}}
